{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2147-12-21 00:30:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. I understand you've been having abdominal pain, nausea, and vomiting since this morning?"
    },
    {
      "turn_number": 2,
      "time": "2147-12-21 00:32:00",
      "speaker": "Patient",
      "text": "Yes, it started around 4 AM. It's sharp and throbbing. I took tramadol and Ativan, but nothing helped."
    },
    {
      "turn_number": 3,
      "time": "2147-12-21 00:34:00",
      "speaker": "Doctor",
      "text": "I see. You haven’t been able to keep anything down, and your last bowel movement was two days ago?"
    },
    {
      "turn_number": 4,
      "time": "2147-12-21 00:35:00",
      "speaker": "Patient",
      "text": "That’s right. No diarrhea or blood, but I feel really bloated and weak."
    },
    {
      "turn_number": 5,
      "time": "2147-12-21 00:37:00",
      "speaker": "Doctor",
      "text": "We’re going to start with IV fluids to help with dehydration and give you some anti-nausea medication."
    },
    {
      "turn_number": 6,
      "time": "2147-12-21 00:39:00",
      "speaker": "Patient",
      "text": "Okay, that sounds good. My blood sugar has probably been high too—I haven’t taken my insulin."
    },
    {
      "turn_number": 7,
      "time": "2147-12-21 00:41:00",
      "speaker": "Doctor",
      "text": "We checked your glucose—it’s elevated at 360. We’ll give you insulin through the IV to bring it down safely."
    },
    {
      "turn_number": 8,
      "time": "2147-12-21 00:43:00",
      "speaker": "Patient",
      "text": "I’ve had this before—gastroparesis flare. It always hits like this."
    },
    {
      "turn_number": 9,
      "time": "2147-12-21 00:45:00",
      "speaker": "Doctor",
      "text": "Yes, your history shows chronic gastroparesis. We don’t see signs of infection or blockage on the X-ray, so this looks like another flare."
    },
    {
      "turn_number": 10,
      "time": "2147-12-21 00:47:00",
      "speaker": "Patient",
      "text": "The X-ray was okay? No blockage?"
    },
    {
      "turn_number": 11,
      "time": "2147-12-21 00:48:00",
      "speaker": "Doctor",
      "text": "Correct. The bowel gas pattern is normal—no obstruction. We’ll keep monitoring your labs."
    },
    {
      "turn_number": 12,
      "time": "2147-12-21 08:15:00",
      "speaker": "Doctor",
      "text": "Good morning. Your latest blood work shows your kidney function is stable—creatinine is 1.2, which is slightly elevated but not concerning right now."
    },
    {
      "turn_number": 13,
      "time": "2147-12-21 08:17:00",
      "speaker": "Patient",
      "text": "Is that from not drinking? I’ve been so nauseous."
    },
    {
      "turn_number": 14,
      "time": "2147-12-21 08:19:00",
      "speaker": "Doctor",
      "text": "Likely, yes. Dehydration can affect the kidneys temporarily. With fluids, it should improve."
    },
    {
      "turn_number": 15,
      "time": "2147-12-21 08:21:00",
      "speaker": "Patient",
      "text": "And my potassium? I remember last time it was high."
    },
    {
      "turn_number": 16,
      "time": "2147-12-21 08:23:00",
      "speaker": "Doctor",
      "text": "It’s mildly elevated at 5.6. Because of that, we’re holding your lisinopril for now. It can raise potassium."
    },
    {
      "turn_number": 17,
      "time": "2147-12-21 08:25:00",
      "speaker": "Patient",
      "text": "So I shouldn’t take it at home either?"
    },
    {
      "turn_number": 18,
      "time": "2147-12-21 08:27:00",
      "speaker": "Doctor",
      "text": "Not until you see your primary doctor. They’ll check your labs and decide when it’s safe to restart."
    },
    {
      "turn_number": 19,
      "time": "2147-12-21 14:00:00",
      "speaker": "Doctor",
      "text": "How’s the pain today? Any improvement?"
    },
    {
      "turn_number": 20,
      "time": "2147-12-21 14:02:00",
      "speaker": "Patient",
      "text": "A little better. Still nauseous, but I sipped some broth without vomiting."
    },
    {
      "turn_number": 21,
      "time": "2147-12-21 14:04:00",
      "speaker": "Doctor",
      "text": "That’s great progress. We’ll keep advancing your diet slowly—maybe soft foods later today."
    },
    {
      "turn_number": 22,
      "time": "2147-12-21 14:06:00",
      "speaker": "Patient",
      "text": "I’m worried about my diabetes. My A1c was 10.3—way too high."
    },
    {
      "turn_number": 23,
      "time": "2147-12-21 14:08:00",
      "speaker": "Doctor",
      "text": "Yes, your diabetes is not well controlled. We’re continuing your home insulin—Lantus and Humalog—and you’ll need close follow-up."
    },
    {
      "turn_number": 24,
      "time": "2147-12-21 14:10:00",
      "speaker": "Patient",
      "text": "I know I need to do better. Stress and pain make it hard to stay on track."
    },
    {
      "turn_number": 25,
      "time": "2147-12-21 14:12:00",
      "speaker": "Doctor",
      "text": "We understand. Managing chronic conditions is tough. Your PCP can help adjust your plan after discharge."
    },
    {
      "turn_number": 26,
      "time": "2147-12-21 20:30:00",
      "speaker": "Patient",
      "text": "Doctor, I have a bad headache now. It’s pounding on one side."
    },
    {
      "turn_number": 27,
      "time": "2147-12-21 20:32:00",
      "speaker": "Doctor",
      "text": "Could be a migraine. You’re on propranolol, which helps prevent them, but sometimes they still happen."
    },
    {
      "turn_number": 28,
      "time": "2147-12-21 20:34:00",
      "speaker": "Patient",
      "text": "Can I take sumatriptan? That usually works."
    },
    {
      "turn_number": 29,
      "time": "2147-12-21 20:36:00",
      "speaker": "Doctor",
      "text": "Yes, we can give you one dose. But you should avoid taking it with tramadol—there’s a risk of serotonin syndrome."
    },
    {
      "turn_number": 30,
      "time": "2147-12-21 20:38:00",
      "speaker": "Patient",
      "text": "I didn’t know that. I’ve taken them together before."
    },
    {
      "turn_number": 31,
      "time": "2147-12-21 20:40:00",
      "speaker": "Doctor",
      "text": "It’s risky. We’ll prescribe sumatriptan for home use, but please don’t combine it with tramadol or sertraline without checking."
    },
    {
      "turn_number": 32,
      "time": "2147-12-22 07:00:00",
      "speaker": "Doctor",
      "text": "Good news—your nausea has improved, and labs are trending better. We think you’re ready to go home today."
    },
    {
      "turn_number": 33,
      "time": "2147-12-22 07:02:00",
      "speaker": "Patient",
      "text": "That’s great. What about my meds?"
    },
    {
      "turn_number": 34,
      "time": "2147-12-22 07:04:00",
      "speaker": "Doctor",
      "text": "You’ll continue all your usual medications except lisinopril, which stays on hold."
    },
    {
      "turn_number": 35,
      "time": "2147-12-22 07:06:00",
      "speaker": "Patient",
      "text": "And insulin? I need to adjust it?"
    },
    {
      "turn_number": 36,
      "time": "2147-12-22 07:08:00",
      "speaker": "Doctor",
      "text": "You’ll stay on Glargine at night and Humalog with meals, plus the sliding scale. Your PCP should see you in 48 hours."
    },
    {
      "turn_number": 37,
      "time": "2147-12-22 07:10:00",
      "speaker": "Patient",
      "text": "What if I feel sick again?"
    },
    {
      "turn_number": 38,
      "time": "2147-12-22 07:12:00",
      "speaker": "Doctor",
      "text": "If vomiting returns or you can’t keep fluids down, come back. Otherwise, focus on small, frequent meals and staying hydrated."
    },
    {
      "turn_number": 39,
      "time": "2147-12-22 07:14:00",
      "speaker": "Patient",
      "text": "And the headache? Should I see a neurologist?"
    },
    {
      "turn_number": 40,
      "time": "2147-12-22 07:16:00",
      "speaker": "Doctor",
      "text": "The sumatriptan helped, right? Keep using it as needed, but avoid tramadol. Your PCP can refer you if migraines continue."
    },
    {
      "turn_number": 41,
      "time": "2147-12-22 07:18:00",
      "speaker": "Patient",
      "text": "Okay, I’ll follow up. Thank you for helping me feel better."
    },
    {
      "turn_number": 42,
      "time": "2147-12-22 07:20:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care, and call your doctor if anything changes."
    },
    {
      "turn_number": 43,
      "time": "2147-12-22 10:00:00",
      "speaker": "Doctor",
      "text": "Just a final check before discharge. You’re alert, walking fine, and your vitals are stable."
    },
    {
      "turn_number": 44,
      "time": "2147-12-22 10:02:00",
      "speaker": "Patient",
      "text": "I feel much better than yesterday. Ready to go home."
    },
    {
      "turn_number": 45,
      "time": "2147-12-22 10:04:00",
      "speaker": "Doctor",
      "text": "We’ll send your discharge instructions and prescriptions. Remember—no lisinopril, no tramadol with sumatriptan."
    },
    {
      "turn_number": 46,
      "time": "2147-12-22 10:06:00",
      "speaker": "Patient",
      "text": "Got it. Thank you again."
    },
    {
      "turn_number": 47,
      "time": "2147-12-22 10:08:00",
      "speaker": "Doctor",
      "text": "Safe travels. We’ll see you soon through your PCP."
    },
    {
      "turn_number": 48,
      "time": "2147-12-22 10:10:00",
      "speaker": "Patient",
      "text": "I’ll make that appointment today."
    },
    {
      "turn_number": 49,
      "time": "2147-12-22 10:12:00",
      "speaker": "Doctor",
      "text": "Perfect. Take care of yourself."
    },
    {
      "turn_number": 50,
      "time": "2147-12-22 10:14:00",
      "speaker": "Patient",
      "text": "I will. Thanks for everything."
    }
  ],
  "summary": {
    "admission_start": "2147-12-21 00:18:00",
    "admission_end": "2147-12-22 17:15:00",
    "summary_paragraph": "A woman with a history of gastroparesis, type 2 diabetes, and chronic abdominal pain was admitted for acute nausea, vomiting, and abdominal pain. She had not tolerated oral intake and presented with hyperglycemia and mild acute kidney injury likely due to dehydration. Supportive care with IV fluids, insulin, and antiemetics led to symptom improvement. Her potassium was mildly elevated, so lisinopril was held. A migraine developed during admission and responded to sumatriptan, with instructions to avoid concurrent tramadol due to serotonin syndrome risk. She advanced to a regular diet, remained stable, and was discharged home with follow-up planned with her primary care provider within 48 hours for medication review and diabetes management.",
    "problems": [
      "Type 2 diabetes mellitus with diabetic autonomic (poly)neuropathy",
      "Acute kidney failure, unspecified",
      "Hyperkalemia",
      "Type 2 diabetes mellitus with hyperglycemia",
      "Essential (primary) hypertension",
      "Gastroparesis",
      "Anxiety disorder, unspecified",
      "Long term (current) use of insulin",
      "Gastro-esophageal reflux disease without esophagitis",
      "Major depressive disorder, single episode, unspecified",
      "Obesity, unspecified",
      "Personal history of urinary (tract) infections",
      "Migraine, unspecified, not intractable, without status migrainosus",
      "Unspecified asthma, uncomplicated",
      "Elevated white blood cell count, unspecified",
      "Anemia, unspecified",
      "Body mass index [BMI] 40.0-44.9, adult"
    ]
  }
}
